<?php
namespace App\Http\Controllers;use App\Models\MeasurementPoint;use App\Models\Survey;use Illuminate\Http\JsonResponse;use Illuminate\Http\Request;
class MeasurementPointController extends Controller{
 public function store(Request $r,Survey $survey):JsonResponse{abort_unless($r->user()->can('measurements.create'),403);abort_unless(in_array($survey->status,['draft','collecting','paused']),422);$d=$r->validate(['survey_run_id'=>'nullable|exists:survey_runs,id','survey_area_id'=>'nullable|exists:survey_areas,id','x_normalized'=>'required|numeric|between:0,1','y_normalized'=>'required|numeric|between:0,1','source_type'=>'required|in:measured,imported,simulated','collection_method'=>'required|string|max:40','notes'=>'nullable|string|max:2000','captured_at'=>'nullable|date']);$d+=['floor_plan_id'=>$survey->floor_plan_id,'captured_by'=>$r->user()->id,'validation_status'=>'pending','captured_at'=>$d['captured_at']??now()];return response()->json($survey->points()->create($d),201);}
 public function update(Request $r,MeasurementPoint $measurementPoint):JsonResponse{abort_unless($r->user()->can('measurements.create'),403);abort_unless($measurementPoint->survey->status!=='completed',422);$d=$r->validate(['x_normalized'=>'sometimes|numeric|between:0,1','y_normalized'=>'sometimes|numeric|between:0,1','notes'=>'nullable|string|max:2000','validation_status'=>'sometimes|in:pending,valid,rejected']);$measurementPoint->update($d);return response()->json($measurementPoint->refresh());}
 public function destroy(Request $r,MeasurementPoint $measurementPoint):JsonResponse{abort_unless($r->user()->can('measurements.create'),403);abort_unless($measurementPoint->survey->status!=='completed',422);$measurementPoint->delete();return response()->json(null,204);}
}
